#!/usr/bin/env bash
# Generate the firstmate-owned Pi primary watcher extension under state/.
set -eu

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FM_ROOT="${FM_ROOT_OVERRIDE:-$(cd "$SCRIPT_DIR/.." && pwd)}"
FM_HOME="${FM_HOME:-${FM_ROOT_OVERRIDE:-$FM_ROOT}}"
STATE="${FM_STATE_OVERRIDE:-$FM_HOME/state}"
OUT="$STATE/fm-primary-pi-watch.ts"

mkdir -p "$STATE"
TMP=$(mktemp "$STATE/fm-primary-pi-watch.ts.XXXXXX") || exit 1
trap '[ -z "${TMP:-}" ] || rm -f "$TMP"' EXIT
cat > "$TMP" <<'EOF'
// Generated by bin/fm-pi-watch-extension.sh.
// Firstmate primary watcher bridge for Pi.
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";

type ArmResult = {
  ok: boolean;
  message: string;
};

export default function (pi: any) {
  const fmHome = process.env.FM_HOME || process.env.FM_ROOT_OVERRIDE || process.cwd();
  const fmRoot = process.env.FM_ROOT_OVERRIDE || process.cwd();
  const state = process.env.FM_STATE_OVERRIDE || `${fmHome}/state`;
  const config = process.env.FM_CONFIG_OVERRIDE || `${fmHome}/config`;
  const armScript = `${fmRoot}/bin/fm-watch-arm.sh`;
  const marker = `${state}/.pi-watch-extension-loaded`;
  let child: any = null;
  let seq = 0;

  function markLoaded() {
    mkdirSync(state, { recursive: true });
    writeFileSync(marker, `${new Date().toISOString()}\n`);
  }

  function actionableLine(output: string): string {
    const lines = output.split(/\r?\n/);
    return lines.find((line) => /^(signal:|stale:|check:|heartbeat($|:))/.test(line)) || "";
  }

  function failureLine(stdout: string, stderr: string, code: number | null): string {
    const combined = `${stdout}\n${stderr}`.trim();
    const failed = combined.split(/\r?\n/).find((line) => /^watcher: FAILED/.test(line));
    if (failed) return failed;
    if (code && code !== 0) return `watcher: FAILED - fm-watch-arm.sh exited ${code}${combined ? `\n${combined}` : ""}`;
    return "";
  }

  async function sendWake(message: string) {
    await pi.sendUserMessage(
      `FIRSTMATE WATCHER WAKE: ${message}\n\nRun bin/fm-wake-drain.sh first, handle the queued wake, then resume Pi supervision.`,
      { deliverAs: "followUp" },
    );
  }

  function startArm(): ArmResult {
    markLoaded();
    if (child) return { ok: true, message: "watcher: healthy - Pi extension already has an arm child" };
    const id = ++seq;
    const env = {
      ...process.env,
      FM_HOME: fmHome,
      FM_ROOT_OVERRIDE: fmRoot,
      FM_CONFIG_OVERRIDE: config,
      FM_WATCH_ARM_SCRIPT: armScript,
    };
    child = spawn("bash", ["-lc", "config_dir=\"${FM_CONFIG_OVERRIDE:-$FM_HOME/config}\"; [ -f \"$config_dir/x-mode.env\" ] && . \"$config_dir/x-mode.env\"; exec \"$FM_WATCH_ARM_SCRIPT\""], {
      cwd: fmRoot,
      env,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString();
    });
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
    });
    child.on("close", async (code: number | null) => {
      child = null;
      const reason = actionableLine(`${stdout}\n${stderr}`);
      const failure = reason ? "" : failureLine(stdout, stderr, code);
      if (!reason && !failure) return;
      try {
        await sendWake(reason || failure);
      } catch {
        // Pi owns delivery errors; fail open so the extension never wedges the session.
      }
    });
    child.on("error", async (error: Error) => {
      child = null;
      try {
        await sendWake(`watcher: FAILED - Pi extension arm child ${id} failed: ${error.message}`);
      } catch {
        // Fail open.
      }
    });
    return { ok: true, message: `watcher: started Pi extension arm child ${id}` };
  }

  pi.on?.("session_start", markLoaded);
  pi.on?.("session_shutdown", () => {
    if (child) child.kill("TERM");
    child = null;
  });

  pi.registerCommand?.("fm-watch-arm-pi", {
    description: "Arm firstmate watcher supervision through the Pi extension.",
    handler: async () => startArm().message,
  });

  pi.registerTool?.({
    name: "fm_watch_arm_pi",
    description: "Arm firstmate watcher supervision through the Pi extension.",
    parameters: {
      type: "object",
      properties: {},
      additionalProperties: false,
    },
    execute: async () => startArm(),
  });

  markLoaded();
}
EOF
if [ -f "$OUT" ] && cmp -s "$TMP" "$OUT"; then
  rm -f "$TMP"
  TMP=
else
  mv "$TMP" "$OUT"
  TMP=
fi
printf '%s\n' "$OUT"
